import{_ as t,o as s,c as a,a2 as n}from"./chunks/framework.CorrxQUb.js";const u=JSON.parse('{"title":"Desktop App","description":"harness9 Desktop is the macOS desktop client of harness9 (phase 1), benchmarked against the OpenAI Codex desktop app:...","frontmatter":{"title":"Desktop App","description":"harness9 Desktop is the macOS desktop client of harness9 (phase 1), benchmarked against the OpenAI Codex desktop app:..."},"headers":[],"relativePath":"docs/desktop-app.md","filePath":"docs/desktop-app.md"}'),o={name:"docs/desktop-app.md"};function i(r,e,d,l,p,c){return s(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="desktop-app" tabindex="-1">Desktop App <a class="header-anchor" href="#desktop-app" aria-label="Permalink to &quot;Desktop App&quot;">​</a></h1><p>harness9 Desktop is the macOS desktop client of harness9 (phase 1), benchmarked against the OpenAI Codex desktop app: a session workspace, streaming conversation, human approvals, and a Plan/Diff review loop — all on top of the same Go engine. Phase 1 is macOS-only; the stack is Wails v2 (Go embedding WKWebView in-process) + React/TypeScript.</p><hr><h2 id="file-layout" tabindex="-1">File Layout <a class="header-anchor" href="#file-layout" aria-label="Permalink to &quot;File Layout&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>desktop/                            # Nested Go module (Wails desktop app)</span></span>
<span class="line"><span>├── go.mod                          # module github.com/harness9/desktop + replace ../</span></span>
<span class="line"><span>├── wails.json                      # Wails project config (product name/version/frontend build)</span></span>
<span class="line"><span>├── main.go                         # Entry: Wails runtime assembly + log redirection</span></span>
<span class="line"><span>├── app.go                          # Binding layer: appservice → frontend methods + event bridge</span></span>
<span class="line"><span>├── build/</span></span>
<span class="line"><span>│   ├── appicon.png                 # App icon (1024x1024)</span></span>
<span class="line"><span>│   └── bin/harness9.app            # Build artifact (ad-hoc signed)</span></span>
<span class="line"><span>└── frontend/                       # React + TypeScript + Vite</span></span>
<span class="line"><span>    └── src/</span></span>
<span class="line"><span>        ├── types.ts                # Type contract mirroring the Go DTOs</span></span>
<span class="line"><span>        ├── store.ts                # zustand store + event assembly (mirrors TUI handleEvent)</span></span>
<span class="line"><span>        ├── App.tsx                 # Layout skeleton and bootstrap flow</span></span>
<span class="line"><span>        └── components/</span></span>
<span class="line"><span>            ├── Sidebar.tsx         # Session list / new task / sandbox &amp; model status</span></span>
<span class="line"><span>            ├── Chat.tsx            # Conversation: Markdown/Thinking/tool cards/token bar</span></span>
<span class="line"><span>            ├── Composer.tsx        # Input: slash completion (/skill + built-ins)</span></span>
<span class="line"><span>            ├── ApprovalModal.tsx   # Five-option approval dialog (queued approvals)</span></span>
<span class="line"><span>            ├── RightPanel.tsx      # Plan progress / Diff review tabbed panel</span></span>
<span class="line"><span>            ├── SettingsDialog.tsx  # Settings (model/permission mode/sandbox backend)</span></span>
<span class="line"><span>            └── Welcome.tsx         # Working-directory picker</span></span>
<span class="line"><span>internal/appservice/                # Application service layer (core, see below)</span></span></code></pre></div><hr><h2 id="architecture-the-codex-style-three-layers" tabindex="-1">Architecture: the Codex-style Three Layers <a class="header-anchor" href="#architecture-the-codex-style-three-layers" aria-label="Permalink to &quot;Architecture: the Codex-style Three Layers&quot;">​</a></h2><p>Codex&#39;s product line (CLI / IDE extension / macOS app) shares one Rust core, with a JSON-RPC app-server protocol on top serving multiple clients. harness9 adopts the same layering, but phase 1 picks the lighter in-process form:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─ harness9.app (Wails v2) ─────────────────────────────┐</span></span>
<span class="line"><span>│  React frontend (WKWebView)                            │</span></span>
<span class="line"><span>│   ▲ agent:event pushes          ▼ bound methods        │</span></span>
<span class="line"><span>│  app.go thin binding layer (no business logic)         │</span></span>
<span class="line"><span>└──────────────┬────────────────────────────────────────┘</span></span>
<span class="line"><span>               │ in-process calls (desktop module replaces main module)</span></span>
<span class="line"><span>┌──────────────▼────────────────────────────────────────┐</span></span>
<span class="line"><span>│  internal/appservice — application service layer       │</span></span>
<span class="line"><span>│   sharedStack (cross-session) + SessionStack (per chat)│</span></span>
<span class="line"><span>│   event pump · approval bridge · sessions · diff       │</span></span>
<span class="line"><span>└──────┬───────────────────┬────────────────────────────┘</span></span>
<span class="line"><span>       │                   │</span></span>
<span class="line"><span>  engine / tools /      internal/sandbox</span></span>
<span class="line"><span>  hooks / memory        (Docker + Seatbelt backends)</span></span>
<span class="line"><span>  (reused as-is)</span></span></code></pre></div><p>Key decisions:</p><ul><li><strong><code>internal/appservice</code> is the single source of assembly truth.</strong> The assembly sequence in <code>cmd/harness9/main.go</code> (env → observability → skills → provider → sandbox → memory → ltm → tools → mcp → hooks → subagent → compactor → engine) is parameterized and extracted; the desktop app no longer duplicates main.go.</li><li><strong>A nested Go module solves <code>internal/</code> visibility.</strong> Go&#39;s internal rule is a lexical directory-tree check: <code>desktop/go.mod</code> references the main module via <code>replace github.com/harness9 =&gt; ../</code>, and the importing directory sits inside the main module&#39;s tree, so <code>internal/</code> packages are importable. The nested module is also skipped automatically by the main module&#39;s <code>go build ./...</code>, so CI and GoReleaser are untouched.</li><li><strong>DTO first.</strong> Every service-layer data structure crossing the boundary is JSON-serializable (<code>SessionInfoDTO</code>/<code>ApprovalData</code>/<code>HistoryItem</code>/<code>DiffResult</code>…). When phase 2 moves the service into a standalone JSON-RPC-over-stdio app-server process (the full Codex shape), the interface carries over without redesign.</li></ul><h3 id="sharedstack-vs-sessionstack" tabindex="-1">sharedStack vs SessionStack <a class="header-anchor" href="#sharedstack-vs-sessionstack" aria-label="Permalink to &quot;sharedStack vs SessionStack&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Stack</th><th>Lifetime</th><th>Contents</th></tr></thead><tbody><tr><td>sharedStack</td><td>Service (per workDir)</td><td>provider, OTEL, skills index, sandbox environment, memory.Manager, LTM Store/Precis, MCP Manager, common hooks (perm/danger/obs)</td></tr><tr><td>SessionStack</td><td>Session (rebuilt on open/create)</td><td>engine, HookRegistry, tool registry (incl. task tool), PlanStore, OffloadHook, CompactionOffloader, ProgressiveCompactor, SubAgent Runner</td></tr></tbody></table><p>Rebuilding the whole session stack is deliberate: OffloadHook / FilePlanWriter / CompactionOffloader all bind to a sessionID, so per-session rebuilds keep offload files and compaction records attributed correctly (also fixing the TUI issue where switching sessions kept writing offloads under the old sessionID). The cost is a few struct initializations; heavyweight resources like the provider and sandbox containers stay shared.</p><hr><h2 id="event-protocol" tabindex="-1">Event Protocol <a class="header-anchor" href="#event-protocol" aria-label="Permalink to &quot;Event Protocol&quot;">​</a></h2><p><code>Service.SendMessage</code> starts <code>engine.RunStream</code> with single-flight semantics; a background goroutine pumps events to the listener (forwarded by the desktop app as Wails <code>EventsEmit(&quot;agent:event&quot;, evt)</code>):</p><table tabindex="0"><thead><tr><th>Event Type</th><th>Payload</th><th>Frontend rendering</th></tr></thead><tbody><tr><td><code>action_delta</code></td><td>string</td><td>streaming Markdown reply</td></tr><tr><td><code>thinking_delta</code></td><td>string</td><td>dark collapsible block (auto-expanded while streaming)</td></tr><tr><td><code>tool_start</code></td><td><code>schema.ToolCall</code></td><td>tool card (running state)</td></tr><tr><td><code>tool_result</code></td><td><code>engine.ToolResultData</code></td><td>card backfilled with output/duration/error state</td></tr><tr><td><code>token_update</code></td><td><code>engine.TokenUpdateData</code></td><td>bottom token gauge (green/yellow/red tiers)</td></tr><tr><td><code>compaction</code></td><td><code>memory.CompactionRecord</code></td><td>&quot;context compacted&quot; notice</td></tr><tr><td><code>sub_agent</code></td><td><code>schema.SubAgentUpdate</code></td><td>sub-agent progress card (aggregated per agent)</td></tr><tr><td><code>approval_required</code></td><td><strong><code>ApprovalData</code></strong> (service DTO, not the raw engine struct)</td><td>queued into the approval dialog</td></tr><tr><td><code>done</code> / <code>error</code></td><td>nil / string</td><td>finalize: flush stream buffers, refresh Plan &amp; Diff</td></tr></tbody></table><p>Two concurrency decisions that differ from the TUI:</p><ol><li><strong>Approvals never block the pump.</strong> The engine&#39;s event channel is unbuffered; the TUI pauses reads while a dialog is open and relies on &quot;only one tool requests approval at a time&quot;. The appservice pump registers approval requests into <code>pendingApprovals</code> and keeps consuming, so concurrent tool approvals cannot deadlock and the UI simply queues dialogs.</li><li><strong>Exactly-once, non-blocking responses.</strong> <code>RespondApproval(id, ...)</code> delivers the decision to the engine&#39;s <code>ResponseCh</code>; if the run was already cancelled (receiver gone), the response is dropped after a 30s timeout and the goroutine exits with the Service context.</li></ol><p>Frontend assembly rules (<code>store.ts</code>): streaming deltas accumulate into buffers; tool boundaries (tool_start / done / error) flush them into timeline entries. Opening a historical session renders directly from the <code>HistoryItem</code> timeline (tool calls and results merged into one card).</p><hr><h2 id="human-in-the-loop-approvals" tabindex="-1">Human-in-the-Loop Approvals <a class="header-anchor" href="#human-in-the-loop-approvals" aria-label="Permalink to &quot;Human-in-the-Loop Approvals&quot;">​</a></h2><p>The approval dialog matches the TUI&#39;s five-option semantics exactly:</p><table tabindex="0"><thead><tr><th>Option</th><th>Behavior</th></tr></thead><tbody><tr><td>Allow once</td><td><code>ApprovalResponse{Approved: true}</code></td></tr><tr><td>Always allow</td><td><code>Approved: true, Remember: true</code> + whitelist write</td></tr><tr><td>Deny</td><td><code>Approved: false</code> (tool returns an IsError result to the LLM)</td></tr><tr><td>Deny with feedback</td><td><code>Approved: false, Feedback: &quot;…&quot;</code> (feedback returned verbatim, triggering self-healing)</td></tr></tbody></table><p>&quot;Always allow&quot; persists a whitelist rule — ported from the TUI&#39;s <code>writeApprovalToConfig</code>: bash builds a glob from the command&#39;s first word (e.g. <code>bash(*git*)</code>), other tools are allowed by tool name, written to <code>&lt;workDir&gt;/.harness9/settings.json</code>. <code>permission.NewFileHook</code> re-reads the file on every tool call, so rules take effect immediately.</p><p>The dialog header is colored by <code>RiskLevel</code> (high/medium from DangerHook, or the default ask from permission rules) and previews the arguments JSON. Multiple simultaneous approvals are queued and handled one at a time.</p><hr><h2 id="plan-diff-review-loop" tabindex="-1">Plan / Diff Review Loop <a class="header-anchor" href="#plan-diff-review-loop" aria-label="Permalink to &quot;Plan / Diff Review Loop&quot;">​</a></h2><p>Benchmarked against Codex&#39;s review loop:</p><ul><li><strong>Plan panel</strong>: the right-hand tab renders the <code>PlanStore</code> item states (pending ○ / in_progress ◐ / completed ● / cancelled ⊘) with a progress bar; refreshed automatically after <code>done</code>. Plan auto-continuation (plan_write triggered) still lives in the engine + TUI semantics; the desktop app only displays.</li><li><strong>Diff panel</strong>: <code>GetSessionDiff</code> runs <code>git status --porcelain</code> + <code>git diff HEAD</code> (--stat + patch) in the workDir; the frontend splits the patch per file into collapsible blocks with +/- line coloring and lists untracked files separately. Phase-1 semantics are &quot;all uncommitted changes in the workDir&quot; (no worktree task isolation yet; once phase 2 lands, diffs will be scoped precisely to the task branch).</li></ul><hr><h2 id="seatbelt-the-macos-native-sandbox-new-backend" tabindex="-1">Seatbelt: the macOS Native Sandbox (new backend) <a class="header-anchor" href="#seatbelt-the-macos-native-sandbox-new-backend" aria-label="Permalink to &quot;Seatbelt: the macOS Native Sandbox (new backend)&quot;">​</a></h2><p>Following Codex&#39;s approach on macOS, a new <code>sandbox.SeatbeltEnvironment</code> (<code>internal/sandbox/seatbelt.go</code>) implements the existing <code>Environment</code> interface:</p><ul><li>Every <code>RunBash</code> spawns the child via <code>sandbox-exec -p &lt;profile&gt; bash -c &lt;cmd&gt;</code> with a <strong>deny-by-default</strong> profile: <code>(deny default)</code> + <code>(import &quot;system.sb&quot;)</code> + full read + process exec/fork;</li><li>The <strong>workspace-write</strong> tier adds writable roots (workDir / TMPDIR / ~/.harness9, all symlink-resolved — macOS /tmp and /var point into /private, and unresolved roots fail silently) plus network;</li><li>The <strong>read-only</strong> tier denies writes and network, suited to read-only exploration;</li><li>File tools (read_file/write_file) still use host IO + the <code>safePath</code> path sandbox, matching the Docker backend&#39;s bind-mount semantics.</li></ul><p>Relationship to the Docker backend: Seatbelt has no container lifecycle (no Manager, no daemon dependency, instant start) and is the desktop app&#39;s first-class default; Docker offers stronger container-grade hard isolation. Switch via the settings dialog or the <code>SANDBOX_BACKEND</code> env var (<code>seatbelt</code> / <code>docker</code> / <code>off</code>). The positioning is a behavior guardrail, not an adversarial security boundary (same threat-model wording as NetworkBlockedHosts).</p><p>Three companion semantics keep the backend consistent: <strong>sub-agent delegation inherits the parent environment</strong> (under Seatbelt the child base tools explicitly share the parent environment, closing the escalation hole where the parent session is sandboxed but delegated work is not; the Docker backend still has the Runner create a separate container per child); <strong>a dedicated system-prompt section</strong> (<code>WithSeatbeltContext</code> uses its own copy that honestly states &quot;real macOS, not root, workspace-writable only&quot; — reusing the Docker copy of &quot;root in Ubuntu, operations cannot affect the real system&quot; would be false and dangerous); <strong>behavior-level evals</strong> (the two <code>sandbox_backend</code> cases drive a real sandbox-exec and assert both allow and deny sides, with the deny side proven by the side effect that the file must not land).</p><p>Desktop settings persist in <code>~/.harness9/desktop/settings.json</code> (model / permission mode / sandbox backend / recent workdirs). Effective timing: permission mode applies on the next opened session (read during session-stack rebuild); model and sandbox backend require an app restart. API keys still come from the workDir&#39;s <code>.env</code> and never enter the settings file.</p><hr><h2 id="session-management" tabindex="-1">Session Management <a class="header-anchor" href="#session-management" aria-label="Permalink to &quot;Session Management&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Implementation</th></tr></thead><tbody><tr><td>List</td><td><code>memory.Manager.ListSessions</code> (updated_at DESC, with title/message count)</td></tr><tr><td>Create</td><td>Every launch and &quot;＋ New Task&quot; creates a new session (TUI semantics)</td></tr><tr><td>Resume</td><td><code>OpenSession</code> rebuilds the session stack + returns the <code>HistoryItem</code> timeline</td></tr><tr><td>Title</td><td><code>sessions</code> table gains a <code>title</code> column (PRAGMA probe + idempotent ALTER TABLE, lossless for old DBs); auto-derived from the first line of the first message (30 chars); rename via double-click in the sidebar</td></tr><tr><td>Delete</td><td><code>DeleteSession</code> cascades messages/plans/offload dirs/compaction records; running sessions cannot be deleted</td></tr></tbody></table><hr><h2 id="build-run" tabindex="-1">Build &amp; Run <a class="header-anchor" href="#build-run" aria-label="Permalink to &quot;Build &amp; Run&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Prerequisites: Go 1.25+, Node 18+, Xcode CLT, wails CLI</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> github.com/wailsapp/wails/v2/cmd/wails@latest</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> desktop</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wails</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # Artifact: desktop/build/bin/harness9.app (arm64, ad-hoc signed)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">open</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/bin/harness9.app</span></span></code></pre></div><p>Development mode (frontend hot reload): <code>cd desktop &amp;&amp; wails dev</code>.</p><p>Runtime logs go to <code>~/.harness9/desktop/logs/app.log</code> (all stdlib log output redirected, since stderr is invisible in GUI processes).</p><hr><h2 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing&quot;">​</a></h2><ul><li><code>internal/appservice</code> unit tests: session lifecycle, event pump (including concurrent approvals: allow+whitelist persistence, deny+feedback round-trip), <code>historyToItems</code> merging, git diff collection, settings round-trip, permission mode conversion;</li><li><code>internal/sandbox/seatbelt_test.go</code>: real <code>sandbox-exec</code> smoke tests (workspace-write can write workDir / out-of-root writes denied / read-only denies writes and network / network tiers), auto-skipped off darwin;</li><li>Existing engine tests and the eval golden dataset show zero regression (the service layer changes no agent-behavior semantics).</li></ul><hr><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Framework</th><th>Borrowed ideas</th></tr></thead><tbody><tr><td>OpenAI Codex</td><td>app-server layering (core → service → multi-client), approval-policy/sandbox-policy separation, macOS Seatbelt sandbox, diff review loop, thread title/persistence/resume</td></tr><tr><td>Claude Code</td><td>five-option approval interaction (allow / always allow / deny / deny with feedback), tool-card information density</td></tr><tr><td>Wails v2</td><td>single-language Go desktop shell, in-process bindings, WKWebView packaging</td></tr></tbody></table>`,52)])])}const g=t(o,[["render",i]]);export{u as __pageData,g as default};
